// language: JavaScript (browser)
// file: jszip.min.js
// purpose: minimal ZIP writer with Zip64

(function (global) {
  'use strict';

  const CRC_TABLE = (() => {
    const t = new Uint32Array(256);
    for (let i = 0; i < 256; i++) {
      let c = i;
      for (let k = 0; k < 8; k++) c = (c & 1) ? (0xEDB88320 ^ (c >>> 1)) : (c >>> 1);
      t[i] = c >>> 0;
    }
    return t;
  })();
  function crc32(u8) {
    let c = 0xFFFFFFFF;
    for (let i = 0; i < u8.length; i++) c = CRC_TABLE[(c ^ u8[i]) & 0xFF] ^ (c >>> 8);
    return (c ^ 0xFFFFFFFF) >>> 0;
  }
  async function deflateRaw(u8) {
    if (typeof CompressionStream === 'undefined') return null;
    try {
      const stream = new Blob([u8]).stream().pipeThrough(new CompressionStream('deflate-raw'));
      return new Uint8Array(await new Response(stream).arrayBuffer());
    } catch (_) { return null; }
  }
  async function toU8(d) {
    if (d instanceof Uint8Array) return d;
    if (d instanceof ArrayBuffer) return new Uint8Array(d);
    if (typeof Blob !== 'undefined' && d instanceof Blob) return new Uint8Array(await d.arrayBuffer());
    if (typeof d === 'string') return new TextEncoder().encode(d);
    return new TextEncoder().encode(String(d));
  }
  function dosDateTime(d) {
    const y = Math.max(1980, d.getFullYear());
    return {
      date: ((y - 1980) << 9) | ((d.getMonth() + 1) << 5) | d.getDate(),
      time: (d.getHours() << 11) | (d.getMinutes() << 5) | (d.getSeconds() >> 1)
    };
  }

  const ZIP64_LIMIT = 0xFFFFFFFF;

  class JSZip {
    constructor() { this._entries = []; }
    file(path, data) { this._entries.push({ path: String(path), data, date: new Date() }); return this; }

    async generateAsync(opts, onProgress) {
      opts = opts || {};
      const outType = opts.type || 'blob';
      const chunks = [];
      const central = [];
      let offset = 0;
      const total = this._entries.length;

      for (let i = 0; i < total; i++) {
        const e = this._entries[i];
        const raw = await toU8(e.data);
        const crc = crc32(raw);
        const uncompSize = raw.length;
        let method = 0, payload = raw;
        if (uncompSize > 32) {
          const d = await deflateRaw(raw);
          if (d && d.length < raw.length) { payload = d; method = 8; }
        }
        const compSize = payload.length;
        const nameBytes = new TextEncoder().encode(e.path);
        const { date, time } = dosDateTime(e.date);

        const needsZip64Local = uncompSize >= ZIP64_LIMIT || compSize >= ZIP64_LIMIT || offset >= ZIP64_LIMIT;
        const extra = needsZip64Local
          ? (() => {
              const x = new Uint8Array(4 + 24);
              const v = new DataView(x.buffer);
              v.setUint16(0, 0x0001, true);
              v.setUint16(2, 24, true);
              v.setBigUint64(4, BigInt(uncompSize), true);
              v.setBigUint64(12, BigInt(compSize), true);
              v.setBigUint64(20, BigInt(offset), true);
              return x;
            })()
          : new Uint8Array(0);

        const lfh = new Uint8Array(30 + nameBytes.length + extra.length);
        const dv = new DataView(lfh.buffer);
        dv.setUint32(0, 0x04034b50, true);
        dv.setUint16(4, needsZip64Local ? 45 : 20, true);
        dv.setUint16(6, 0, true);
        dv.setUint16(8, method, true);
        dv.setUint16(10, time, true);
        dv.setUint16(12, date, true);
        dv.setUint32(14, crc, true);
        dv.setUint32(18, compSize >= ZIP64_LIMIT ? 0xFFFFFFFF : compSize, true);
        dv.setUint32(22, uncompSize >= ZIP64_LIMIT ? 0xFFFFFFFF : uncompSize, true);
        dv.setUint16(26, nameBytes.length, true);
        dv.setUint16(28, extra.length, true);
        lfh.set(nameBytes, 30);
        if (extra.length) lfh.set(extra, 30 + nameBytes.length);

        chunks.push(lfh, payload);
        central.push({ nameBytes, method, time, date, crc, compSize, uncompSize, offset, extra });
        offset += lfh.length + payload.length;
        if (onProgress) onProgress({ percent: ((i + 1) / total) * 100 });
      }

      const cdStart = offset;
      let cdSize = 0;

      for (const e of central) {
        const cdh = new Uint8Array(46 + e.nameBytes.length + e.extra.length);
        const dv = new DataView(cdh.buffer);
        dv.setUint32(0, 0x02014b50, true);
        dv.setUint16(4, e.extra.length ? 45 : 20, true);
        dv.setUint16(6, e.extra.length ? 45 : 20, true);
        dv.setUint16(8, 0, true);
        dv.setUint16(10, e.method, true);
        dv.setUint16(12, e.time, true);
        dv.setUint16(14, e.date, true);
        dv.setUint32(16, e.crc, true);
        dv.setUint32(20, e.compSize >= ZIP64_LIMIT ? 0xFFFFFFFF : e.compSize, true);
        dv.setUint32(24, e.uncompSize >= ZIP64_LIMIT ? 0xFFFFFFFF : e.uncompSize, true);
        dv.setUint16(28, e.nameBytes.length, true);
        dv.setUint16(30, e.extra.length, true);
        dv.setUint16(32, 0, true);
        dv.setUint16(34, 0, true);
        dv.setUint16(36, 0, true);
        dv.setUint32(38, 0, true);
        dv.setUint32(42, e.offset >= ZIP64_LIMIT ? 0xFFFFFFFF : e.offset, true);
        cdh.set(e.nameBytes, 46);
        if (e.extra.length) cdh.set(e.extra, 46 + e.nameBytes.length);
        chunks.push(cdh);
        cdSize += cdh.length;
      }

      const needZip64 = central.length > 0xFFFF || cdSize >= ZIP64_LIMIT || cdStart >= ZIP64_LIMIT;

      if (needZip64) {
        const z64 = new Uint8Array(56);
        const dv = new DataView(z64.buffer);
        dv.setUint32(0, 0x06064b50, true);
        dv.setBigUint64(4, BigInt(44), true);
        dv.setUint16(12, 45, true);
        dv.setUint16(14, 45, true);
        dv.setUint32(16, 0, true);
        dv.setUint32(20, 0, true);
        dv.setBigUint64(24, BigInt(central.length), true);
        dv.setBigUint64(32, BigInt(central.length), true);
        dv.setBigUint64(40, BigInt(cdSize), true);
        dv.setBigUint64(48, BigInt(cdStart), true);
        chunks.push(z64);

        const loc = new Uint8Array(20);
        const lv = new DataView(loc.buffer);
        lv.setUint32(0, 0x07064b50, true);
        lv.setUint32(4, 0, true);
        lv.setBigUint64(8, BigInt(cdStart + cdSize), true);
        lv.setUint32(16, 1, true);
        chunks.push(loc);
      }

      const eocd = new Uint8Array(22);
      const dv = new DataView(eocd.buffer);
      dv.setUint32(0, 0x06054b50, true);
      dv.setUint16(4, 0, true);
      dv.setUint16(6, 0, true);
      dv.setUint16(8, needZip64 ? 0xFFFF : central.length, true);
      dv.setUint16(10, needZip64 ? 0xFFFF : central.length, true);
      dv.setUint32(12, needZip64 ? 0xFFFFFFFF : cdSize, true);
      dv.setUint32(16, needZip64 ? 0xFFFFFFFF : cdStart, true);
      dv.setUint16(20, 0, true);
      chunks.push(eocd);

      const blob = new Blob(chunks, { type: 'application/zip' });
      if (outType === 'blob') return blob;
      if (outType === 'uint8array') return new Uint8Array(await blob.arrayBuffer());
      if (outType === 'arraybuffer') return await blob.arrayBuffer();
      return blob;
    }
  }

  global.JSZip = JSZip;
})(typeof window !== 'undefined' ? window : globalThis);